CREATE DATABASE IF NOT EXISTS fixnest; USE fixnest;
CREATE TABLE customers (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, phone VARCHAR(15) NOT NULL UNIQUE, email VARCHAR(120));
CREATE TABLE services (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, emoji VARCHAR(10), description VARCHAR(255), price DECIMAL(10,2) NOT NULL, active BOOLEAN DEFAULT TRUE);
CREATE TABLE bookings (id BIGINT AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT NOT NULL, service_id BIGINT NOT NULL, booking_date DATE NOT NULL, time_slot VARCHAR(20) NOT NULL, address VARCHAR(255) NOT NULL,
  status ENUM('PENDING','CONFIRMED','COMPLETED','CANCELLED') DEFAULT 'PENDING', amount DECIMAL(10,2) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (customer_id) REFERENCES customers(id), FOREIGN KEY (service_id) REFERENCES services(id));
CREATE TABLE payments (id BIGINT AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT NOT NULL UNIQUE, amount DECIMAL(10,2) NOT NULL, method VARCHAR(30),
  status ENUM('PENDING','PAID','FAILED') DEFAULT 'PENDING', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (booking_id) REFERENCES bookings(id));
CREATE TABLE chatbot_faq (id BIGINT AUTO_INCREMENT PRIMARY KEY, question VARCHAR(255) NOT NULL, answer VARCHAR(500) NOT NULL, category VARCHAR(50));
-- Relations: customer 1-* bookings, service 1-* bookings, booking 1-1 payment
